trait Customer { def name: String }
trait CustomerRole { def core: Customer }

final class CustomerCore(val name: String) extends Customer {   // core owns the role map
  private val roles = scala.collection.mutable.Map.empty[Class[?], CustomerRole]
  def addRole[T <: CustomerRole](spec: Class[T], role: T): T = { roles(spec) = role; role }
  def getRole[T <: CustomerRole](spec: Class[T]): Option[T] = roles.get(spec).map(spec.cast)
}
trait BorrowerRole extends CustomerRole {                       // self-type pins the role to a core
  def borrow(amount: Long): String = s"${core.name} borrows $amount"
}
val borrower = customer.addRole(classOf[BorrowerRole], new BorrowerRole { val core = customer })
